 function editLine(i,key,value){setLines(old=>old.map((l,j)=>j===i?{...l,[key]:value}:l));}
 async function request(url,body,message){setBusy(true);try{await api(url,{method:'POST',body});await onChange();notify(message);return true;}catch(e){notify(e.message);return false;}finally{setBusy(false);}}
