 function open(type,record,line){setOperation({type,id:record.id,lineId:line?.id,quantity:'',amount:'',customer:'',reason:'',supplier:record.preferred_supplier||'',reorderLevel:record.reorder_level||'0',reorderQuantity:record.reorder_quantity||'0',key:crypto.randomUUID(),label:line?.item_name||record.name||record.po_number});}
