 return <div className="settings-group"><h3>Autonomous world engine</h3>{error&&<p className="settings-note">{error}</p>}{status&&<><div className="settings-row"><div><b>{label}</b><small>Engine revision {status.engine.revision??'—'} / expected {status.engine.expectedRevision} · {status.engine.active?'Worker heartbeat active':'No recent worker heartbeat'}</small></div><span>{status.health==='healthy'?'●':status.health==='degraded'?'!':'○'}</span></div><p className="settings-note">Last world processing: {status.world.lastCheckedAt?new Date(status.world.lastCheckedAt).toLocaleString():'Not recorded'} · Last engine tick: {status.engine.lastTickAt?new Date(status.engine.lastTickAt).toLocaleString():'Not recorded'}</p><p className="settings-note">External indicators: {status.external.signalsAt?new Date(status.external.signalsAt).toLocaleString():'Not yet refreshed'} · News: {status.external.newsAt?new Date(status.external.newsAt).toLocaleString():'Not yet refreshed'}</p>{failures.length>0&&<div className="detail-section"><b>Stages needing attention</b>{failures.map(x=><p key={x.stage}>{x.stage} · {x.consecutive_failures} consecutive failure(s) · {x.last_error_code||'error'}</p>)}</div>}</>}<button onClick={check} disabled={busy}>Refresh engine diagnostics</button> <button onClick={activate} disabled={busy}>Activate / recover engine</button><small className="settings-note">Heartbeat and provider acceptance do not guarantee a notification was displayed or a phone call rang. Browser delivery still requires device testing.</small></div>;
